import { Component, Element, Host, Prop, h } from "@stencil/core";
import { hasSlot } from "../../utils/slot";

/**
 * @since 2.11.0
 * @status beta
 *
 * @part base - The base element that wraps the entire filter bar.
 * @part start - The element that wraps the start slot.
 * @part filters - The element that wraps the default slot for filters.
 * @part fixed - The element that wraps the fixed slot for always-visible elements.
 * @part end - The element that wraps the end slot.
 * @part collapsible - The element that wraps the collapsible part of the filter bar, which includes both the filters and fixed slots.
 * @part hidden - The element that wraps hidden filters when they overflow.
 *
 * @slot start - The slot for elements at the start of the filter bar, such as a search input.
 * @slot fixed - The slot for elements that should always be visible in the filter bar, such as persistent filters.
 * @slot overflow - The slot where the overflow button is shown when filters are hidden.
 * @slot fixed-suffix - The slot for elements fixed at the end of the filter bar, such as a total count.
 * @slot end - The slot for elements at the end of the filter bar.
 */

@Component({
	tag: "hbr-filter-bar",
	styleUrl: "filter-bar.scss",
	shadow: true,
})
export class FilterBar {
	@Element() host: HTMLHbrFilterBarElement;

	@Prop({ reflect: true }) size: "small" | "medium" = "medium";

	private readonly _gap = { small: 6, medium: 8 };
	private readonly _offset = 0;

	private _resizeObserver: ResizeObserver;
	private _base: HTMLElement;
	private _start: HTMLElement;
	private _filters: HTMLElement;
	private _fixed: HTMLElement;
	private _end: HTMLElement;
	private _collapsible: HTMLElement;

	private _hasStart: boolean;
	private _hasFixed: boolean;
	private _hasOverflow: boolean;
	private _hasFixedSuffix: boolean;

	private getTotalWidth(): number {
		return (
			this._start.clientWidth +
			this._collapsible.clientWidth +
			this._end.clientWidth
		);
	}

	private handleShowAndHide(): void {
		const visibleElements = this.getDefaultSlotNodes();
		const totalWidth = this.getTotalWidth();

		if (totalWidth > this._base.clientWidth) {
			this.hideLastElement(visibleElements);
		} else {
			this.showFirstHiddenElement(totalWidth);
		}

		if (this.getDefaultSlotNodes().length === 0) {
			this._filters.classList.add("filter-bar--filters-hide");
		} else {
			this._filters.classList.remove("filter-bar--filters-hide");
		}

		this.updateOverflowSlots();
	}

	private hideLastElement(elements: HTMLElement[]): void {
		if (elements.length) {
			elements[elements.length - 1].setAttribute("slot", "hide");
		}
	}

	private showFirstHiddenElement(totalWidth: number): void {
		const hiddenElements = this.getHiddenElements();
		if (
			hiddenElements.length &&
			totalWidth +
				hiddenElements[0].clientWidth +
				this._gap[this.size] +
				this._offset <
				this._base.clientWidth
		) {
			hiddenElements[0].removeAttribute("slot");
		}
	}

	private updateOverflowSlots(): void {
		const hiddenElements = this.getHiddenElements();
		const overflowSlot = this.host.querySelector("[slot='overflow']");
		const overflowHideSlot = this.host.querySelector("[slot='overflow-hide']");

		if (!hiddenElements.length) {
			overflowSlot?.setAttribute("slot", "overflow-hide");
		} else {
			overflowHideSlot?.setAttribute("slot", "overflow");
		}
	}

	private getDefaultSlotNodes(): HTMLElement[] {
		const slot = this._filters.querySelector("slot");
		const assignedNodes = slot.assignedNodes();
		return assignedNodes.filter(
			(node) => node.nodeType === Node.ELEMENT_NODE,
		) as HTMLElement[];
	}

	private getHiddenElements(): HTMLElement[] {
		return Array.from(this.host.querySelectorAll("[slot='hide']"));
	}

	private initializeResizeObserver(): void {
		this._resizeObserver = new ResizeObserver(() => this.handleShowAndHide());
		this._resizeObserver.observe(this._base);
		this._resizeObserver.observe(this._collapsible);
	}

	private handleSlotChange(): void {
		this._hasStart = hasSlot(this.host, "start");
		this._hasFixed = hasSlot(this.host, "fixed");
		this._hasOverflow = hasSlot(this.host, "overflow");
		this._hasFixedSuffix = hasSlot(this.host, "fixed-suffix");
	}

	componentDidLoad(): void {
		this._base = this.host.shadowRoot.querySelector("[part='base']");
		this._start = this.host.shadowRoot.querySelector("[part='start']");
		this._filters = this.host.shadowRoot.querySelector("[part='filters']");
		this._fixed = this.host.shadowRoot.querySelector("[part='fixed']");
		this._end = this.host.shadowRoot.querySelector("[part='end']");
		this._collapsible = this.host.shadowRoot.querySelector(
			"[part='collapsible']",
		);

		if (!this._base || !this._filters || !this._fixed || !this._end) return;

		this.initializeResizeObserver();
	}

	connectedCallback(): void {
		this.handleSlotChange = this.handleSlotChange.bind(this);
	}

	disconnectedCallback(): void {
		this._resizeObserver?.disconnect();
	}

	componentWillLoad(): void {
		this.handleSlotChange();
	}

	render() {
		return (
			<Host>
				<div
					class={{
						"filter-bar": true,
						"filter-bar--small": this.size === "small",
						"filter-bar--medium": this.size === "medium",
					}}
					part="base"
				>
					<div
						class={{ "filter-bar--start-hide": !this._hasStart }}
						part="start"
					>
						<slot name="start" onSlotchange={this.handleSlotChange} />
					</div>
					<div class="filter-bar--collapsible" part="collapsible">
						<div class="filter-bar--filters" part="filters">
							<slot onSlotchange={this.handleSlotChange} />
						</div>
						<div
							class={{
								"filter-bar--fixed":
									this._hasFixed || this._hasOverflow || this._hasFixedSuffix,
							}}
							part="fixed"
						>
							<slot name="fixed" onSlotchange={this.handleSlotChange} />
							<slot name="overflow" onSlotchange={this.handleSlotChange} />
							<slot name="fixed-suffix" onSlotchange={this.handleSlotChange} />
						</div>
					</div>
					<div class="filter-bar--end" part="end">
						<slot name="end" />
					</div>
				</div>
				<div class="filter-bar--hidden" part="hidden" inert>
					<slot name="hide" />
					<slot name="overflow-hide" />
				</div>
			</Host>
		);
	}
}
